foreach ( $paragraphs as $i => $text ) {
	$tag = ( 0 === $i ) ? 'h2' : 'p';
	if ( $i > 0 && preg_match( '/^\d+\.\s*[А-ЯЁA-Z]/u', $text ) && mb_strlen( $text ) < 90 ) {
